$trace = [];
$a = function ($r, $next) use (&$trace) {
    $trace[] = 'outer-in';
    $result = $next($r);
    $trace[] = 'outer-out';
    return $result;
};
$b = function ($r, $next) use (&$trace) {
    $trace[] = 'paused';
    return response('maintenance', 503);
};
$c = function ($r, $next) use (&$trace) {
    $trace[] = 'later';
    return $next($r);
};
app(Illuminate\Pipeline\Pipeline::class)->send(null)->through([$a, $b, $c])->then(function () use (&$trace) {
    $trace[] = 'controller';
});
echo implode(',', $trace);

