$closed = false;
$next = function () { throw new RuntimeException('failed'); };
try {
    try {
        $next();
    } finally {
        $closed = true;
    }
} catch (RuntimeException $e) {
    echo ($closed ? 'closed' : 'open').':propagated';
}

